import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyPhuongTienCuDan = () => {
    const [userRoom, setUserRoom] = useState('');
    const [vehicleList, setVehicleList] = useState([]);
    const [loading, setLoading] = useState(true);

    // Khởi tạo thông tin cư dân
    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        const room = profile.room_id || profile.room || '102'; 
        setUserRoom(room);
        fetchVehicles(room);
    }, []);

    // --- CHUẨN BỊ CHO BACKEND: FETCH DỮ LIỆU XE ---
    const fetchVehicles = async (room) => {
        setLoading(true);
        try {
            /* SAU NÀY GẮN API THỰC TẾ:
            const res = await fetch(`/api/vehicles/room/${room}`);
            const data = await res.json();
            setVehicleList(data);
            */

            // GIẢ LẬP: Đợi 0.5s để thấy hiệu ứng loading chuyên nghiệp
            setTimeout(() => {
                const allData = JSON.parse(localStorage.getItem('all_vehicles') || '{}');
                // Nếu backend chưa có data, trả về mảng mẫu để test giao diện
                setVehicleList(allData[room] || [
                    { type: 'Xe máy', plate: '43-K1 123.45' },
                    { type: 'Ô tô', plate: '30H-888.88' }
                ]);
                setLoading(false);
            }, 500);
        } catch (error) {
            console.error("Lỗi kết nối:", error);
            setLoading(false);
        }
    };

    return (
        <div style={containerStyle} className="glass-card">
            {/* Header: Kính đen mờ 0.3 */}
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🚗 PHƯƠNG TIỆN CỦA TÔI</h2>
                <div style={roomBadge}>Phòng {userRoom}</div>
            </div>

            <div style={contentWrapperStyle}>
                {/* Form trắng đặc (Solid White) - Giống hệt trang Hóa Đơn */}
                <div style={mainFormCard}>
                    {loading ? (
                        <div style={statusMsg}>Đang truy xuất dữ liệu...</div>
                    ) : (
                        <div style={{ animation: 'fadeIn 0.4s', height: '100%', display: 'flex', flexDirection: 'column' }}>

                            {/* Khung số phòng nét đứt đặc trưng */}
                            <div style={roomDisplay}>
                                <span style={{ fontSize: '13px', color: '#8b5e5e', fontWeight: 'bold' }}>SỐ LƯỢNG XE ĐĂNG KÝ</span>
                                <div style={{ fontSize: '42px', fontWeight: '900', color: '#333' }}>
                                    {vehicleList.length} <span style={{fontSize: '18px', color: '#8b5e5e'}}>xe</span>
                                </div>
                            </div>

                            {/* Danh sách xe đổ từ backend/storage */}
                            <div className="custom-scrollbar" style={listScrollStyle}>
                                {vehicleList.length > 0 ? vehicleList.map((vehicle, index) => (
                                    <div key={index} style={vehicleCard}>
                                        <div style={cardRow}>
                                            <span style={labelStyle}>Loại phương tiện:</span>
                                            <span style={valueStyle}>{vehicle.type}</span>
                                        </div>
                                        <div style={cardRow}>
                                            <span style={labelStyle}>Biển kiểm soát:</span>
                                            <span style={plateStyle}>{vehicle.plate}</span>
                                        </div>
                                    </div>
                                )) : (
                                    <div style={emptyState}>Chưa có phương tiện đăng ký.</div>
                                )}
                            </div>

                            <p style={footerNote}>* Mọi thay đổi vui lòng liên hệ Ban quản lý tòa nhà.</p>
                        </div>
                    )}
                </div>
            </div>

            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #eee; border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- STYLES ĐỒNG BỘ CHUẨN XEMHOADON.JS ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)' };
const roomBadge = { padding: '6px 15px', background: '#fff', borderRadius: '12px', color: '#8b5e5e', fontWeight: 'bold', fontSize: '14px' };
const contentWrapperStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '20px' };

// Khối trắng đặc, bóng mờ đậm chuẩn 0.2
const mainFormCard = { 
    width: '100%', 
    maxWidth: '480px', 
    backgroundColor: '#fff', 
    borderRadius: '30px', 
    padding: '35px', 
    boxShadow: '0 15px 35px rgba(0,0,0,0.2)', 
    display: 'flex', 
    flexDirection: 'column',
    maxHeight: '85%'
};

const roomDisplay = { textAlign: 'center', padding: '15px', background: '#fdf3f3', borderRadius: '20px', marginBottom: '25px', border: '2px dashed #8b5e5e' };
const listScrollStyle = { flex: 1, overflowY: 'auto', paddingRight: '5px' };

const vehicleCard = { padding: '18px', backgroundColor: '#f9f9f9', borderRadius: '18px', marginBottom: '12px', border: '1px solid #eee' };
const cardRow = { display: 'flex', justifyContent: 'space-between', marginBottom: '5px' };
const labelStyle = { color: '#888', fontSize: '13px' };
const valueStyle = { fontWeight: 'bold', fontSize: '15px', color: '#333' };
const plateStyle = { fontWeight: '900', fontSize: '20px', color: '#8b5e5e', letterSpacing: '1px' };

const statusMsg = { textAlign: 'center', color: '#8b5e5e', fontWeight: 'bold' };
const emptyState = { textAlign: 'center', color: '#ccc', padding: '50px 0' };
const footerNote = { textAlign: 'center', fontSize: '11px', color: '#bbb', marginTop: '20px', fontStyle: 'italic' };

export default QuanLyPhuongTienCuDan;
